const fs = require('fs')
const path = require('path')

const appFile = './src/App.jsx'
const backup = './src/App.jsx.step20-template-style-backup'
const templateDir = './public'
const templateFile = './public/mcross-estimate-template.xlsx'
const marker = '/* M-CROSS_STEP20_TEMPLATE_STYLE_FIX */'

if (!fs.existsSync(appFile)) {
  console.error('src/App.jsxが見つかりません。')
  process.exit(1)
}

let s = fs.readFileSync(appFile, 'utf8')
if (s.includes(marker)) {
  console.log('STEP20 テンプレート版は適用済みです')
  process.exit(0)
}
if (!s.includes('/* M-CROSS_STEP20_ESTIMATE_EXPORT */')) {
  console.error('STEP20が見つかりません。変更しませんでした。')
  process.exit(1)
}

fs.mkdirSync(templateDir, { recursive: true })
fs.writeFileSync(templateFile, Buffer.from('', 'base64'))

const functionStart = s.indexOf('  async function exportWorkOrderEstimate(workOrder) {')
const nextFunction = s.indexOf('\n  function updateWorkOrder(', functionStart)
if (functionStart === -1 || nextFunction === -1) {
  console.error('STEP20見積出力関数の範囲が見つかりません。変更しませんでした。')
  process.exit(1)
}

const replacement = `  ${marker}
  async function exportWorkOrderEstimate(workOrder) {
    if (!workOrder) return
    const items = Array.isArray(workOrder.estimateItems) ? workOrder.estimateItems : []
    if (!items.length) {
      window.alert('見積明細がありません。')
      return
    }
    if (items.length > 32) {
      window.alert('見積書テンプレートは32明細までです。明細を整理してから出力してください。')
      return
    }

    try {
      const { default: ExcelJS } = await import('exceljs')
      const templateUrl = new URL('/mcross-estimate-template.xlsx', window.location.origin).toString()
      const templateResponse = await fetch(templateUrl, { cache: 'no-store' })
      if (!templateResponse.ok) throw new Error('見積書テンプレートを読み込めません HTTP ' + templateResponse.status)

      const workbook = new ExcelJS.Workbook()
      await workbook.xlsx.load(await templateResponse.arrayBuffer())
      const ws = workbook.getWorksheet('見積書')
      if (!ws) throw new Error('テンプレートの「見積書」シートが見つかりません')

      // 工事カードへの外部参照をM-Crossの値へ置換。テンプレートの書式はそのまま使います。
      ws.getCell('B5').value = (workOrder.company || '') + (workOrder.company ? '　御中' : '')
      ws.getCell('J5').value = new Date()
      ws.getCell('B6').value = ''
      ws.getCell('D13').value = workOrder.propertyName || ''
      ws.getCell('F13').value = workOrder.unit || ''
      ws.getCell('G13').value = workOrder.unit ? '号室' : ''
      ws.getCell('D14').value = workOrder.address || ''

      // テンプレートの明細欄 23～54行を初期化してからM-Cross明細を流し込みます。
      for (let rowNumber = 23; rowNumber <= 54; rowNumber += 1) {
        ws.getCell('C' + rowNumber).value = ''
        ws.getCell('F' + rowNumber).value = ''
        ws.getCell('H' + rowNumber).value = ''
        ws.getCell('I' + rowNumber).value = ''
        ws.getCell('J' + rowNumber).value = ''
        ws.getCell('K' + rowNumber).value = { formula: 'H' + rowNumber + '*J' + rowNumber }
      }

      items.forEach((item, index) => {
        const rowNumber = 23 + index
        ws.getCell('C' + rowNumber).value = item.name || ''
        ws.getCell('F' + rowNumber).value = item.specification || ''
        ws.getCell('H' + rowNumber).value = Number(item.quantity || 0)
        ws.getCell('I' + rowNumber).value = item.unit || ''
        ws.getCell('J' + rowNumber).value = Number(item.unitPrice || 0)
        ws.getCell('K' + rowNumber).value = Number(item.amount || 0)
      })

      // テンプレート本来の小計→消費税→合計を維持。
      ws.getCell('K55').value = { formula: 'SUM(K23:K54)' }
      ws.getCell('K56').value = { formula: 'ROUNDDOWN(K55*0.1,0)' }
      ws.getCell('K57').value = { formula: 'SUM(K55:K56)' }
      ws.getCell('E19').value = { formula: 'K57' }

      const buffer = await workbook.xlsx.writeBuffer()
      const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' })
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = ['見積書', workOrder.propertyName || '物件', workOrder.unit ? workOrder.unit + '号室' : ''].filter(Boolean).join('_') + '.xlsx'
      document.body.appendChild(link)
      link.click()
      link.remove()
      URL.revokeObjectURL(url)
      updateWorkOrder(workOrder.id, { estimateStatus: '提出済' })
    } catch (error) {
      console.error(error)
      window.alert('見積書を出力できませんでした：' + (error?.message || String(error)))
    }
  }
`

fs.copyFileSync(appFile, backup)
s = s.slice(0, functionStart) + replacement + s.slice(nextFunction)
fs.writeFileSync(appFile, s, 'utf8')

console.log('STEP20 見積書テンプレート完全利用版 OK')
console.log('見積書テンプレート.xlsx を public/mcross-estimate-template.xlsx として組み込みました')
console.log('M-Crossはテンプレートのレイアウト・書式を使い、値だけ差し替えて出力します')
console.log('明細は23～54行、小計K55、消費税K56、合計K57へ反映します')
console.log('バックアップ:', backup)
console.log('次に npm run build を実行してください')
